mapper.select:
SELECT content.post_type,content.category_id,content.id,
       content.type,
       content.title,
       content.content_preview,
       content.author_id,
       content.author_name,
       content.status,
       content.audit_status,
       content.pinned,
       content.featured,
       content.report_count,
       content.view_count,
       content.like_count,
       content.comment_count,
       content.share_count,
       content.published_at,
       content.updated_at,
       content.deleted_at,
       content.raw_status
FROM () content
WHERE 1 = 1 AND NOT EXISTS(SELECT 1 FROM post_growth_record g WHERE g.post_id=CASE WHEN content.type='post' THEN content.id ELSE (SELECT c.target_id FROM comment c WHERE c.id=content.id AND c.target_type=1) END)

    AND content.authorization_namespace IN #{space}


    AND content.type = #{type}

AND content.type='post' AND content.post_type=#{postType}
AND content.type='post' AND content.category_id=#{categoryId}
AND content.type='post' AND EXISTS(SELECT 1 FROM post_topic pt WHERE pt.post_id=content.id AND pt.topic_id=#{topicId})

    AND content.status = #{status}


    AND content.pinned = TRUE


    AND content.featured = TRUE


    AND content.report_count > 0


    AND (

            content.id = #{keywordId} OR

        content.title LIKE CONCAT('%', #{keyword}, '%')
        OR content.content_preview LIKE CONCAT('%', #{keyword}, '%')
        OR content.author_name LIKE CONCAT('%', #{keyword}, '%')
        OR CAST(content.author_id AS CHAR) = #{keyword}
    )


    AND (
        content.updated_at < #{cursorUpdatedAt}
        OR (content.updated_at = #{cursorUpdatedAt} AND content.type > #{cursorType})
        OR (content.updated_at = #{cursorUpdatedAt} AND content.type = #{cursorType}
            AND content.id < #{cursorId})
    )


    AND (
        COALESCE(content.view_count, 0) < #{cursorMetric}
        OR (COALESCE(content.view_count, 0) = #{cursorMetric}
            AND content.updated_at < #{cursorUpdatedAt})
        OR (COALESCE(content.view_count, 0) = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type > #{cursorType})
        OR (COALESCE(content.view_count, 0) = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type = #{cursorType}
            AND content.id < #{cursorId})
    )


    AND (
        content.report_count < #{cursorMetric}
        OR (content.report_count = #{cursorMetric} AND content.updated_at < #{cursorUpdatedAt})
        OR (content.report_count = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type > #{cursorType})
        OR (content.report_count = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type = #{cursorType}
            AND content.id < #{cursorId})
    )



        ORDER BY COALESCE(content.view_count, 0) DESC,
                 content.updated_at DESC, content.type ASC, content.id DESC


        ORDER BY content.report_count DESC,
                 content.updated_at DESC, content.type ASC, content.id DESC


        ORDER BY content.updated_at DESC, content.type ASC, content.id DESC


LIMIT #{limit}

SELECT content.post_type,content.category_id,content.id,
       content.type,
       content.title,
       content.content_preview,
       content.author_id,
       content.author_name,
       content.status,
       content.audit_status,
       content.pinned,
       content.featured,
       content.report_count,
       content.view_count,
       content.like_count,
       content.comment_count,
       content.share_count,
       content.published_at,
       content.updated_at,
       content.deleted_at,
       content.raw_status
FROM () content
WHERE EXISTS(SELECT 1 FROM post_growth_record g WHERE g.post_id=CASE WHEN content.type='post' THEN content.id ELSE (SELECT c.target_id FROM comment c WHERE c.id=content.id AND c.target_type=1) END
AND g.record_type=#{growthType}
AND g.organization_id=#{growthOrganizationId}
AND g.organization_id IN #{org})

    AND content.authorization_namespace IN #{space}


    AND content.type = #{type}

AND content.type='post' AND content.post_type=#{postType}
AND content.type='post' AND content.category_id=#{categoryId}
AND content.type='post' AND EXISTS(SELECT 1 FROM post_topic pt WHERE pt.post_id=content.id AND pt.topic_id=#{topicId})

    AND content.status = #{status}


    AND content.pinned = TRUE


    AND content.featured = TRUE


    AND content.report_count > 0


    AND (

            content.id = #{keywordId} OR

        content.title LIKE CONCAT('%', #{keyword}, '%')
        OR content.content_preview LIKE CONCAT('%', #{keyword}, '%')
        OR content.author_name LIKE CONCAT('%', #{keyword}, '%')
        OR CAST(content.author_id AS CHAR) = #{keyword}
    )


    AND (
        content.updated_at < #{cursorUpdatedAt}
        OR (content.updated_at = #{cursorUpdatedAt} AND content.type > #{cursorType})
        OR (content.updated_at = #{cursorUpdatedAt} AND content.type = #{cursorType}
            AND content.id < #{cursorId})
    )


    AND (
        COALESCE(content.view_count, 0) < #{cursorMetric}
        OR (COALESCE(content.view_count, 0) = #{cursorMetric}
            AND content.updated_at < #{cursorUpdatedAt})
        OR (COALESCE(content.view_count, 0) = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type > #{cursorType})
        OR (COALESCE(content.view_count, 0) = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type = #{cursorType}
            AND content.id < #{cursorId})
    )


    AND (
        content.report_count < #{cursorMetric}
        OR (content.report_count = #{cursorMetric} AND content.updated_at < #{cursorUpdatedAt})
        OR (content.report_count = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type > #{cursorType})
        OR (content.report_count = #{cursorMetric}
            AND content.updated_at = #{cursorUpdatedAt} AND content.type = #{cursorType}
            AND content.id < #{cursorId})
    )



        ORDER BY COALESCE(content.view_count, 0) DESC,
                 content.updated_at DESC, content.type ASC, content.id DESC


        ORDER BY content.report_count DESC,
                 content.updated_at DESC, content.type ASC, content.id DESC


        ORDER BY content.updated_at DESC, content.type ASC, content.id DESC


LIMIT #{limit}

SELECT COALESCE(SUM(content.status='published'),0) published,COALESCE(SUM(content.status='pending'),0) pending,
  COALESCE(SUM(content.report_count>0),0) reported,COALESCE(SUM(content.status='removed' AND content.deleted_at>=CURRENT_DATE),0) removed_today
FROM () content
WHERE EXISTS(SELECT 1 FROM post_growth_record g WHERE g.post_id=CASE WHEN content.type='post' THEN content.id ELSE (SELECT c.target_id FROM comment c WHERE c.id=content.id AND c.target_type=1) END
AND g.record_type=#{growthType}
AND g.organization_id=#{growthOrganizationId}
AND g.organization_id IN #{o})
AND content.type=#{type}
